from pathlib import Path
from html import escape
from PIL import Image
import json

ROOT = Path(__file__).parent
ASSETS = ROOT / 'assets'
ASSETS.mkdir(exist_ok=True)
SRC = Path(__file__).parents[1] / 'generated_images'
for stem, file in {
    'mandap-concept': 'exec-058c1a0e-aa22-43ae-8d8a-a3b8ab2cdeeb.png',
    'ceremony-concept': 'exec-b985f726-91c8-4fab-b6dc-1dc84d0a739e.png',
    'entrance-concept': 'exec-9ca1e271-0c7c-4f27-aa5b-e3c8e985c9a0.png',
}.items():
    image = Image.open(SRC / file).convert('RGB')
    for width in (600, 1100, 1600):
        if width > image.width: continue
        out = image.resize((width, round(image.height * width / image.width)), Image.Resampling.LANCZOS)
        out.save(ASSETS / f'{stem}-{width}.webp', 'WEBP', quality=80, method=6)

