def picture(stem, alt, cls='', eager=False):
    srcset=f'assets/{stem}-600.webp 600w, assets/{stem}-1100.webp 1100w'
    if stem=='mandap-concept': srcset+=f', assets/{stem}-1600.webp 1600w'
    return f'''<picture class="{cls}"><source type="image/webp" srcset="{srcset}" sizes="(max-width: 700px) 100vw, 50vw"><img src="assets/{stem}-1100.webp" alt="{escape(alt)}" width="1100" height="1000" loading="{'eager' if eager else 'lazy'}" decoding="async"></picture>'''

